const input = $json;
let context = input.context || {};
if (typeof context === 'string') {
  try { context = JSON.parse(context); } catch (e) { context = {}; }
}
const text = (input.message || '').trim();
const state = input.current_state || 'NEW';

const PRICES = { SMALL: 3000, MEDIUM: 4500, LARGE: 6000 };
const SUPPORTED_ROUTES = [
  ['Uyo', 'Aba'], ['Aba', 'Uyo'], ['Uyo', 'Port Harcourt'], ['Port Harcourt', 'Uyo']
];

function normPhone(raw) {
  let p = String(raw).replace(/[^0-9+]/g, '');
  if (p.startsWith('0')) p = '+234' + p.slice(1);
  else if (p.startsWith('234')) p = '+' + p;
  else if (!p.startsWith('+')) p = '+' + p;
  return p;
}

function routeSupported(pickup, dest) {
  const norm = (s) => (s || '').trim().toLowerCase();
  return SUPPORTED_ROUTES.some(([a, b]) => norm(a) === norm(pickup) && norm(b) === norm(dest));
}

let next_state = state;
let reply = '';
let action = 'NONE';

switch (state) {
  case 'NEW':
    next_state = 'AWAITING_PICKUP_LOCATION';
    reply = "Sure! What's the pickup location?";
    break;

  case 'AWAITING_PICKUP_LOCATION':
    context.pickup_location = text;
    next_state = 'AWAITING_DELIVERY_LOCATION';
    reply = "What's the delivery location?";
    break;

  case 'AWAITING_DELIVERY_LOCATION':
    context.delivery_location = text;
    next_state = 'AWAITING_PACKAGE_DESCRIPTION';
    reply = 'What are you sending?';
    break;

  case 'AWAITING_PACKAGE_DESCRIPTION':
    context.package_description = text;
    next_state = 'AWAITING_PACKAGE_SIZE';
    reply = 'What size is the package? Small, Medium, or Large?';
    break;

  case 'AWAITING_PACKAGE_SIZE': {
    const m = text.toUpperCase().match(/SMALL|MEDIUM|LARGE/);
    if (!m) {
      next_state = 'AWAITING_PACKAGE_SIZE';
      reply = 'Please select a package size: Small, Medium, or Large.';
    } else {
      context.package_size = m[0];
      next_state = 'AWAITING_RECIPIENT_NAME';
      reply = "What's the recipient's name?";
    }
    break;
  }

  case 'AWAITING_RECIPIENT_NAME':
    context.recipient_name = text;
    next_state = 'AWAITING_RECIPIENT_PHONE';
    reply = "What's the recipient's phone number?";
    break;

  case 'AWAITING_RECIPIENT_PHONE': {
    const digits = text.replace(/[^0-9]/g, '');
    if (digits.length < 10) {
      next_state = 'AWAITING_RECIPIENT_PHONE';
      reply = "That doesn't look like a valid phone number. Please provide the recipient's phone number.";
    } else {
      context.recipient_phone = normPhone(text);
      const fee = PRICES[context.package_size] || PRICES.MEDIUM;
      context.quote_amount = fee;
      next_state = 'AWAITING_CONFIRMATION';
      reply = `Your estimated delivery fee is \u20a6${fee.toLocaleString()}. Would you like to confirm? (yes/no)`;
    }
    break;
  }

  case 'AWAITING_CONFIRMATION': {
    const t = text.toLowerCase();
    if (/^(yes|yep|yeah|confirm|ok|okay|sure)/.test(t)) {
      if (!routeSupported(context.pickup_location, context.delivery_location)) {
        next_state = 'HUMAN_ESCALATION';
        action = 'ESCALATE_ROUTE';
        reply = "That route isn't in our standard list, so I've sent this to our operations team to confirm pricing and availability. They'll follow up shortly.";
      } else {
        next_state = 'COMPLETED';
        action = 'CREATE_DELIVERY';
        reply = 'PENDING_TRACKING_NUMBER';
      }
    } else if (/^(no|nope|cancel)/.test(t)) {
      next_state = 'IDLE';
      reply = "No problem, your request has been cancelled. Let me know if you'd like to start again.";
      context = {};
    } else {
      next_state = 'AWAITING_CONFIRMATION';
      reply = `Sorry, I didn't catch that. Your estimated delivery fee is \u20a6${(context.quote_amount || 0).toLocaleString()}. Please reply yes to confirm or no to cancel.`;
    }
    break;
  }

  default:
    next_state = 'AWAITING_PICKUP_LOCATION';
    reply = "Let's start again. What's the pickup location?";
}

return [{
  json: {
    customer_id: input.customer_id,
    phone: input.phone,
    conversation_id: input.conversation_id || null,
    next_state,
    context,
    reply,
    action
  }
}];

const base = $('Process Delivery Request State').item.json;
const row = $json;
return [{
  json: {
    ...base,
    reply: `Your delivery request has been created. Your tracking number is ${row.tracking_number}.`,
    tracking_number: row.tracking_number
  }
}];

const f = $('Finalize Payload').item.json;
return [{
  json: {
    reply: f.reply,
    next_state: f.next_state,
    customer_id: f.customer_id,
    conversation_id: f.conversation_id,
    tracking_number: f.tracking_number || null
  }
}];
